INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '111', 2, 'mellin-split-2026-11-24', '{"tag":"8JN4","type":"lemma","title":"Mellin transform and positive residues","statement_tex":"Let $\\mathcal G_\\psi$ be the \\hyperref[8JG8]{weighted sum} and, for $\\Re s > 1$,\n\\[ \\Phi_\\psi(s) = \\int_1^\\infty \\mathcal G_\\psi(x)\\, x^{-s-1}\\, dx. \\]\nLet\n\\[ Z = \\left\\{ \\rho \\in \\C \\;\\middle|\\; \\Re\\rho > 0,\\ L(\\rho, \\chi) = 0 \\text{ for some } \\chi \\in \\mathcal C_\\psi \\right\\}, \\]\na locally finite set, closed under conjugation since $\\mathcal C_\\psi$ is, and let $m_\\chi(\\rho) \\ge 0$ be the multiplicity of $\\rho$ as a zero of $L(s,\\chi)$. Then $\\Phi_\\psi$ continues meromorphically to $\\Re s > 0$, its poles there are exactly the points of $Z$, and each is simple with\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = -\\frac{S_\\rho}{\\rho(\\rho-1)}, \\qquad S_\\rho = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(m_\\chi(\\rho) + m_{\\bar\\chi}(\\rho)\\bigr) > 0. \\]\nIn particular every real $\\rho \\in Z$ lies in $(0,1)$ and has a positive residue.","section_id":104,"position":1,"listed":1,"aliases":["mellin-poles"]}', 'claude');
INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '101', 1, 'mellin-split-2026-11-24', '{"result_id":111,"body_tex":"Since $\\Lambda(n) \\le \\log n$,\n\\[ R_\\chi(x) = O\\bigl(x(1 + \\log^2 x)\\bigr), \\]\nso the integral converges absolutely for $\\Re s > 1$ and may be computed term by term. From\n\\[ \\int_n^\\infty \\Bigl(\\frac xn - 1\\Bigr) x^{-s-1}\\,dx = \\frac{n^{-s}}{s(s-1)} \\]\nwe get\n\\[ \\int_1^\\infty R_\\chi(x) x^{-s-1}\\,dx = -\\frac{L''}{L}(s,\\chi)\\,\\frac{1}{s(s-1)}. \\]\nWith\n\\[ \\int_1^\\infty x \\cdot x^{-s-1}\\,dx = \\frac1{s-1}, \\qquad \\int_1^\\infty x\\log x \\cdot x^{-s-1}\\,dx = \\frac1{(s-1)^2}, \\]\nthe transform $H_\\chi$ of $G_\\chi$ is, with $b_\\chi = L''(1,\\chi)/L(1,\\chi)$,\n\\[ H_\\chi(s) = -\\frac{L''}{L}(s,\\chi)\\frac{1}{s(s-1)} + \\frac{b_\\chi}{s-1} \\quad (\\chi \\ne \\mathbf 1), \\qquad H_{\\mathbf 1}(s) = -\\frac{\\zeta''}{\\zeta}(s)\\frac{1}{s(s-1)} - \\frac{1}{(s-1)^2} + \\frac{1+\\gamma}{s-1}. \\]\nThe singular parts at $s = 1$ cancel. For $\\chi \\ne \\mathbf 1$ the first term has residue $-b_\\chi$ there. For $\\mathbf 1$ use\n\\[ -\\frac{\\zeta''}{\\zeta}(s) = \\frac{1}{s-1} - \\gamma + O(s-1), \\qquad \\frac1s = 1 - (s-1) + O\\bigl((s-1)^2\\bigr). \\]\nSo $H_\\chi$ is meromorphic on $\\Re s > 0$, with poles only at zeros $\\rho$ of $L(s,\\chi)$, where the residue is $-m_\\chi(\\rho)/(\\rho(\\rho-1))$.\n\nFor real $x$ we have $\\overline{G_\\chi(x)} = G_{\\bar\\chi}(x)$, so $\\Re G_\\chi = \\frac12(G_\\chi + G_{\\bar\\chi})$ and\n\\[ \\Phi_\\psi(s) = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(H_\\chi(s) + H_{\\bar\\chi}(s)\\bigr), \\]\nwhich gives the residue formula. Each $a_\\chi > 0$ and some multiplicity is positive, so $S_\\rho > 0$: there is no cancellation between members of the family. Finally $L(s,\\chi) \\ne 0$ for $\\Re s \\ge 1$ \\cite{Davenport}, so a real $\\rho \\in Z$ lies in $(0,1)$, where $\\rho(\\rho - 1) < 0$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
INSERT OR IGNORE INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '102', 2, 'mellin-split-2026-11-24', '{"result_id":113,"body_tex":"\\emph{A one-sided bound.} Put $g(u) = \\mathcal G_\\psi(e^u)$. Then $g$ is real, $|g(u)| \\le C_\\psi e^{2u}$, and\n\\[ \\Phi_\\psi(s) = \\int_0^\\infty g(u) e^{-su}\\,du. \\]\nFix $\\sigma = 336$ and, for $k \\ge 0$, set\n\\[ K_k(u) = \\frac{u^k e^{-\\sigma u}}{k!} \\ge 0, \\qquad A_k(s) = \\frac{(-1)^k}{k!}\\Phi_\\psi^{(k)}(s), \\qquad\\text{so}\\qquad A_k(\\sigma + i\\tau) = \\int_0^\\infty g(u) K_k(u) e^{-i\\tau u}\\,du. \\]\nSince $|g| + g = 2g_+$ with $g_+ = \\max(g, 0)$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le 2\\int_0^\\infty g_+(u) K_k(u)\\,du \\qquad (\\tau \\in \\R). \\]\nSo only an \\emph{upper} bound for $g$ is needed. Take $Y$ from the hypothesis, and\n\\[ U = \\log Y, \\qquad k = \\lceil 420U \\rceil. \\]\nThe kernel $K_k$ peaks at $u = k/\\sigma \\approx \\frac54 U$, inside $[U, \\frac32 U]$, where $g_+(u) \\le e^{\\theta u}$. That range contributes at most\n\\[ \\int_0^\\infty e^{\\theta u} K_k(u)\\,du = (\\sigma - \\theta)^{-k-1}. \\]\nOn the tails use $g_+ \\le C_\\psi e^{2u}$; a direct computation bounds them by $O_\\psi(336^{-k})$. With $D_* = \\sigma - \\theta$ we get, for an unbounded sequence of $k$ and uniformly in $\\tau$,\n\\[ |A_k(\\sigma + i\\tau)| + \\Re A_k(\\sigma) \\le C_* D_*^{-k}. \\tag{$*$} \\]\n\n\\emph{Cauchy''s estimate.} If $\\rho$ is the only pole of $\\Phi_\\psi$ in a closed disk $\\overline B(z, r) \\subset \\left\\{ s \\in \\C \\;\\middle|\\; \\Re s > 0 \\right\\}$, with residue $c$, then, with a constant independent of $k$,\n\\[ A_k(z) = \\frac{c}{(z - \\rho)^{k+1}} + O(r^{-k}). \\]\n\n\\emph{Contradiction.} Suppose some $\\rho_0 \\in Z$ has $\\Re \\rho_0 > \\theta$. Let\n\\[ D = \\min\\bigl(D_*, \\operatorname{dist}(\\sigma, Z)\\bigr), \\]\nso the disk $B(\\sigma, D)$ contains no pole.\n\n(a) Some pole $\\rho_1$ has $\\sigma - \\Re\\rho_1 < D$. For $\\tau$ near $\\Im \\rho_1$, a disk about $z = \\sigma + i\\tau$ of fixed radius less than $D$ contains $\\rho_1$, and for $\\tau$ in a short interval these disks meet only finitely many poles. Two poles with different imaginary parts are equidistant from $z$ for at most one $\\tau$; two with equal imaginary parts never are, as both lie left of $\\Re s = \\sigma$. Avoiding these finitely many $\\tau$, $z$ has a unique nearest pole $\\rho$, at distance $d < D$. Choose $d < r < D$ with $\\rho$ the only pole in $\\overline B(z, r)$. Since $\\overline B(\\sigma, r)$ has no pole and the residue $c$ is nonzero by \\hyperref[8JN4]{the lemma},\n\\[ |A_k(z)| + \\Re A_k(\\sigma) \\ge |c|\\, d^{-k-1} - O(r^{-k}). \\]\nMultiplying $(*)$ by $d^k$ and letting $k \\to \\infty$ gives $|c|/d \\le 0$.\n\n(b) Every pole has $\\sigma - \\Re\\rho \\ge D$. Applied to $\\rho_0$ this gives $D \\le \\sigma - \\Re\\rho_0 < D_*$, so $D = \\operatorname{dist}(\\sigma, Z)$, attained (as $Z$ is locally finite) at some $\\rho$ with\n\\[ |\\sigma - \\rho| = D \\le \\sigma - \\Re\\rho. \\]\nHence $\\rho = \\beta = \\sigma - D$ is real and the unique nearest pole, with residue $c_\\beta > 0$ by \\hyperref[8JN4]{the lemma}. For some $D < r < D_*$,\n\\[ \\Re A_k(\\sigma) = c_\\beta D^{-k-1} + O(r^{-k}), \\]\nwhile $(*)$ with $\\tau = 0$ gives $2\\Re A_k(\\sigma) \\le C_* D_*^{-k}$. Multiplying by $D^k$ gives $c_\\beta / D \\le 0$.\n\nBoth cases are impossible, so $\\Re\\rho \\le \\theta$ for all $\\rho \\in Z$. The positivity of the residue at real poles is what lets a \\emph{one-sided} bound exclude real zeros.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');

-- definition 8JS2 (id 115): Mellin transform
INSERT INTO tags (tag, kind) VALUES ('8JS2', 'result');
INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (115, '8JS2', 'definition', 'Mellin transform', 'Let $c_0 \in \R$ and let $f \colon [1,\infty) \to \C$ be locally integrable with $f(x) = O_\varepsilon(x^{c_0+\varepsilon})$ for every $\varepsilon > 0$. The \emph{Mellin transform} of $f$ is the function
\[ (\mathcal M f)(s) = \int_1^\infty f(x)\, x^{-s-1}\, dx \qquad (\Re s > c_0). \]
The integral converges absolutely for $\Re s > c_0$, since $|f(x)\, x^{-s-1}| \le C_\varepsilon\, x^{c_0 + \varepsilon - \Re s - 1}$ with $\varepsilon < \Re s - c_0$. We use the normalization $x^{-s-1}$, rather than the more common $x^{s-1}$, because it sends $\bigl(\frac xn - 1\bigr)_+$ to $\frac{n^{-s}}{s(s-1)}$.', NULL, 104, 1, 'published', 1, 1, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '115', 1, 'mellin-split-2026-11-24', '{"tag":"8JS2","type":"definition","title":"Mellin transform","statement_tex":"Let $c_0 \\in \\R$ and let $f \\colon [1,\\infty) \\to \\C$ be locally integrable with $f(x) = O_\\varepsilon(x^{c_0+\\varepsilon})$ for every $\\varepsilon > 0$. The \\emph{Mellin transform} of $f$ is the function\n\\[ (\\mathcal M f)(s) = \\int_1^\\infty f(x)\\, x^{-s-1}\\, dx \\qquad (\\Re s > c_0). \\]\nThe integral converges absolutely for $\\Re s > c_0$, since $|f(x)\\, x^{-s-1}| \\le C_\\varepsilon\\, x^{c_0 + \\varepsilon - \\Re s - 1}$ with $\\varepsilon < \\Re s - c_0$. We use the normalization $x^{-s-1}$, rather than the more common $x^{s-1}$, because it sends $\\bigl(\\frac xn - 1\\bigr)_+$ to $\\frac{n^{-s}}{s(s-1)}$.","section_id":104,"position":1,"listed":1,"aliases":["mellin-transform"]}', 'claude');
