-- lemma 8JS3 (id 116): Growth of the smoothed prime sums
INSERT INTO tags (tag, kind) VALUES ('8JS3', 'result');
INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (116, '8JS3', 'lemma', 'Growth of the smoothed prime sums', 'Let $\chi$ be a \hyperref[8JH4]{primitive character} and $G_\chi$ its \hyperref[8JF7]{smoothed prime sum}. There is a constant $C_\chi$ such that
\[ |G_\chi(x)| \le C_\chi\, x\,(1 + \log x)^2 \qquad (x \ge 1). \]
In particular $G_\chi(x) = O_\varepsilon(x^{1+\varepsilon})$ for every $\varepsilon > 0$.', NULL, 104, 2, 'published', 1, 1, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '116', 1, 'mellin-split-2026-11-24', '{"tag":"8JS3","type":"lemma","title":"Growth of the smoothed prime sums","statement_tex":"Let $\\chi$ be a \\hyperref[8JH4]{primitive character} and $G_\\chi$ its \\hyperref[8JF7]{smoothed prime sum}. There is a constant $C_\\chi$ such that\n\\[ |G_\\chi(x)| \\le C_\\chi\\, x\\,(1 + \\log x)^2 \\qquad (x \\ge 1). \\]\nIn particular $G_\\chi(x) = O_\\varepsilon(x^{1+\\varepsilon})$ for every $\\varepsilon > 0$.","section_id":104,"position":2,"listed":1,"aliases":["smoothed-sum-growth"]}', 'claude');
INSERT INTO aliases (alias, tag) VALUES ('smoothed-sum-growth', '8JS3');
