-- lemma 8JS5 (id 118): Conjugation and the zero set
INSERT INTO tags (tag, kind) VALUES ('8JS5', 'result');
INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (118, '8JS5', 'lemma', 'Conjugation and the zero set', 'Let $\psi$ be a primitive character, and let $\mathcal C_\psi$, $m_\chi$, $S_\rho$ and $Z$ be as in \hyperref[8JS4]{the definition}.
\begin{enumerate}
\item[(i)] $Z$ is locally finite: every compact subset of $\C$ contains only finitely many points of $Z$.
\item[(ii)] For every primitive character $\chi$, $\overline{L(\bar s, \chi)} = L(s, \bar\chi)$ as meromorphic functions of $s \in \C$.
\item[(iii)] For every primitive character $\chi$ and every $\rho \in \C$, $m_{\bar\chi}(\bar\rho) = m_\chi(\rho)$.
\item[(iv)] $Z$ is closed under complex conjugation.
\item[(v)] $S_\rho > 0$ for every $\rho \in Z$.
\end{enumerate}', NULL, 104, 4, 'published', 1, 1, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '118', 1, 'mellin-split-2026-11-24', '{"tag":"8JS5","type":"lemma","title":"Conjugation and the zero set","statement_tex":"Let $\\psi$ be a primitive character, and let $\\mathcal C_\\psi$, $m_\\chi$, $S_\\rho$ and $Z$ be as in \\hyperref[8JS4]{the definition}.\n\\begin{enumerate}\n\\item[(i)] $Z$ is locally finite: every compact subset of $\\C$ contains only finitely many points of $Z$.\n\\item[(ii)] For every primitive character $\\chi$, $\\overline{L(\\bar s, \\chi)} = L(s, \\bar\\chi)$ as meromorphic functions of $s \\in \\C$.\n\\item[(iii)] For every primitive character $\\chi$ and every $\\rho \\in \\C$, $m_{\\bar\\chi}(\\bar\\rho) = m_\\chi(\\rho)$.\n\\item[(iv)] $Z$ is closed under complex conjugation.\n\\item[(v)] $S_\\rho > 0$ for every $\\rho \\in Z$.\n\\end{enumerate}","section_id":104,"position":4,"listed":1,"aliases":["zero-set-properties"]}', 'claude');
INSERT INTO aliases (alias, tag) VALUES ('zero-set-properties', '8JS5');
INSERT INTO refs (source_result_id, source_proof_id, target_tag) VALUES (118, NULL, '8JS4');
INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (105, 118, 1, '\emph{(i)} For $\chi \ne \mathbf 1$ the function $L(s,\chi)$ is entire and not identically zero, and $(s-1)\zeta(s)$ is entire and not identically zero, with the same zeros as $\zeta$ \cite{Davenport}. The zeros of a nonzero entire function form a discrete closed subset of $\C$, so a compact set contains only finitely many of them. Since $\mathcal C_\psi$ is finite, $Z$ is contained in a finite union of such sets.

\emph{(ii)} For $\Re s > 1$,
\[ \overline{L(\bar s, \chi)} = \sum_{n \ge 1} \overline{\chi(n)}\, n^{-s} = \sum_{n \ge 1} \bar\chi(n)\, n^{-s} = L(s, \bar\chi). \]
Both sides are meromorphic on $\C$, so they agree everywhere by the identity theorem.

\emph{(iii)} Let $m = m_\chi(\rho)$, and write $L(s,\chi) = (s - \rho)^m g(s)$ near $\rho$, with $g$ holomorphic and $g(\rho) \ne 0$. By (ii), near $\bar\rho$,
\[ L(s, \bar\chi) = \overline{L(\bar s, \chi)} = (s - \bar\rho)^m\, \overline{g(\bar s)}, \]
where $s \mapsto \overline{g(\bar s)}$ is holomorphic and equals $\overline{g(\rho)} \ne 0$ at $s = \bar\rho$. Hence $m_{\bar\chi}(\bar\rho) = m$.

\emph{(iv)} Let $\rho \in Z$, say $L(\rho, \chi) = 0$ with $\chi \in \mathcal C_\psi$. Then $\Re\bar\rho = \Re\rho > 0$, and $L(\bar\rho, \bar\chi) = 0$ by (iii). The family $\mathcal C_\psi$ is closed under $\chi \mapsto \bar\chi$ (\hyperref[8JG8]{definition}), so $\bar\chi \in \mathcal C_\psi$ and $\bar\rho \in Z$.

\emph{(v)} Let $\rho \in Z$, so $m_\chi(\rho) \ge 1$ for some $\chi \in \mathcal C_\psi$. Every term of $S_\rho$ is nonnegative and $a_\chi > 0$, so $S_\rho \ge \frac12 a_\chi m_\chi(\rho) > 0$.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '105', 1, 'mellin-split-2026-11-24', '{"result_id":118,"body_tex":"\\emph{(i)} For $\\chi \\ne \\mathbf 1$ the function $L(s,\\chi)$ is entire and not identically zero, and $(s-1)\\zeta(s)$ is entire and not identically zero, with the same zeros as $\\zeta$ \\cite{Davenport}. The zeros of a nonzero entire function form a discrete closed subset of $\\C$, so a compact set contains only finitely many of them. Since $\\mathcal C_\\psi$ is finite, $Z$ is contained in a finite union of such sets.\n\n\\emph{(ii)} For $\\Re s > 1$,\n\\[ \\overline{L(\\bar s, \\chi)} = \\sum_{n \\ge 1} \\overline{\\chi(n)}\\, n^{-s} = \\sum_{n \\ge 1} \\bar\\chi(n)\\, n^{-s} = L(s, \\bar\\chi). \\]\nBoth sides are meromorphic on $\\C$, so they agree everywhere by the identity theorem.\n\n\\emph{(iii)} Let $m = m_\\chi(\\rho)$, and write $L(s,\\chi) = (s - \\rho)^m g(s)$ near $\\rho$, with $g$ holomorphic and $g(\\rho) \\ne 0$. By (ii), near $\\bar\\rho$,\n\\[ L(s, \\bar\\chi) = \\overline{L(\\bar s, \\chi)} = (s - \\bar\\rho)^m\\, \\overline{g(\\bar s)}, \\]\nwhere $s \\mapsto \\overline{g(\\bar s)}$ is holomorphic and equals $\\overline{g(\\rho)} \\ne 0$ at $s = \\bar\\rho$. Hence $m_{\\bar\\chi}(\\bar\\rho) = m$.\n\n\\emph{(iv)} Let $\\rho \\in Z$, say $L(\\rho, \\chi) = 0$ with $\\chi \\in \\mathcal C_\\psi$. Then $\\Re\\bar\\rho = \\Re\\rho > 0$, and $L(\\bar\\rho, \\bar\\chi) = 0$ by (iii). The family $\\mathcal C_\\psi$ is closed under $\\chi \\mapsto \\bar\\chi$ (\\hyperref[8JG8]{definition}), so $\\bar\\chi \\in \\mathcal C_\\psi$ and $\\bar\\rho \\in Z$.\n\n\\emph{(v)} Let $\\rho \\in Z$, so $m_\\chi(\\rho) \\ge 1$ for some $\\chi \\in \\mathcal C_\\psi$. Every term of $S_\\rho$ is nonnegative and $a_\\chi > 0$, so $S_\\rho \\ge \\frac12 a_\\chi m_\\chi(\\rho) > 0$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
