-- lemma 8JS6 (id 119): Mellin transform of a smoothed prime sum
INSERT INTO tags (tag, kind) VALUES ('8JS6', 'result');
INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (119, '8JS6', 'lemma', 'Mellin transform of a smoothed prime sum', 'Let $\chi$ be a primitive character, $H_\chi$ as in \hyperref[8JS4]{the definition}, and $b_\chi = L''(1,\chi)/L(1,\chi)$ for $\chi \ne \mathbf 1$.
\begin{enumerate}
\item[(i)] For $\Re s > 1$,
\[ H_\chi(s) = -\frac{L''}{L}(s,\chi)\frac{1}{s(s-1)} + \frac{b_\chi}{s-1} \quad (\chi \ne \mathbf 1), \qquad H_{\mathbf 1}(s) = -\frac{\zeta''}{\zeta}(s)\frac{1}{s(s-1)} - \frac{1}{(s-1)^2} + \frac{1+\gamma}{s-1}. \]
\item[(ii)] $H_\chi$ extends meromorphically to $\Re s > 0$. Its poles there are exactly the zeros $\rho$ of $L(s,\chi)$ with $\Re\rho > 0$; each is simple, with
\[ \operatorname{Res}_{s=\rho} H_\chi = -\frac{m_\chi(\rho)}{\rho(\rho-1)}. \]
\end{enumerate}', NULL, 104, 5, 'published', 1, 1, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '119', 1, 'mellin-split-2026-11-24', '{"tag":"8JS6","type":"lemma","title":"Mellin transform of a smoothed prime sum","statement_tex":"Let $\\chi$ be a primitive character, $H_\\chi$ as in \\hyperref[8JS4]{the definition}, and $b_\\chi = L''(1,\\chi)/L(1,\\chi)$ for $\\chi \\ne \\mathbf 1$.\n\\begin{enumerate}\n\\item[(i)] For $\\Re s > 1$,\n\\[ H_\\chi(s) = -\\frac{L''}{L}(s,\\chi)\\frac{1}{s(s-1)} + \\frac{b_\\chi}{s-1} \\quad (\\chi \\ne \\mathbf 1), \\qquad H_{\\mathbf 1}(s) = -\\frac{\\zeta''}{\\zeta}(s)\\frac{1}{s(s-1)} - \\frac{1}{(s-1)^2} + \\frac{1+\\gamma}{s-1}. \\]\n\\item[(ii)] $H_\\chi$ extends meromorphically to $\\Re s > 0$. Its poles there are exactly the zeros $\\rho$ of $L(s,\\chi)$ with $\\Re\\rho > 0$; each is simple, with\n\\[ \\operatorname{Res}_{s=\\rho} H_\\chi = -\\frac{m_\\chi(\\rho)}{\\rho(\\rho-1)}. \\]\n\\end{enumerate}","section_id":104,"position":5,"listed":1,"aliases":["mellin-smoothed-sum"]}', 'claude');
INSERT INTO aliases (alias, tag) VALUES ('mellin-smoothed-sum', '8JS6');
INSERT INTO refs (source_result_id, source_proof_id, target_tag) VALUES (119, NULL, '8JS4');
INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (106, 119, 1, '\emph{(i)} For $n \ge 1$ and $\Re s > 1$,
\[ \int_1^\infty \Bigl(\frac xn - 1\Bigr)_+ x^{-s-1}\,dx = \int_n^\infty \Bigl(\frac xn - 1\Bigr) x^{-s-1}\,dx = \frac{n^{-s}}{s(s-1)}. \]
With $\sigma = \Re s > 1$ and $\Lambda \ge 0$ this gives
\[ \sum_{n \ge 1} \Lambda(n) \int_1^\infty \Bigl(\frac xn - 1\Bigr)_+ x^{-\sigma-1}\,dx = \frac{1}{\sigma(\sigma-1)} \sum_{n \ge 1} \Lambda(n)\, n^{-\sigma} < \infty, \]
so by Fubini the transform of $R_\chi$ may be computed term by term:
\[ \int_1^\infty R_\chi(x)\, x^{-s-1}\,dx = \frac{1}{s(s-1)} \sum_{n \ge 1} \Lambda(n)\chi(n)\, n^{-s} = -\frac{L''}{L}(s,\chi)\,\frac{1}{s(s-1)}. \]
Together with
\[ \int_1^\infty x \cdot x^{-s-1}\,dx = \frac1{s-1}, \qquad \int_1^\infty x\log x \cdot x^{-s-1}\,dx = \frac1{(s-1)^2}, \]
the definition of $G_\chi$ and linearity give the formulas.

\emph{(ii)} The right-hand sides in (i) are meromorphic on $\C$; they give the continuation. In $\Re s > 0$ the rational factors are singular only at $s = 1$, and $-\frac{L''}{L}(s,\chi)$ is singular only at the zeros of $L(s,\chi)$ and, for $\chi = \mathbf 1$, at the pole $s = 1$ of $\zeta$.

\emph{No pole at $s = 1$.} For $\chi \ne \mathbf 1$ we have $L(1,\chi) \ne 0$ \cite{Davenport}, so $-\frac{L''}{L}(s,\chi)$ is holomorphic at $1$ with value $-b_\chi$, and the first term is $-\frac{b_\chi}{s-1} + O(1)$, which cancels $\frac{b_\chi}{s-1}$. For $\chi = \mathbf 1$,
\[ -\frac{\zeta''}{\zeta}(s) = \frac{1}{s-1} - \gamma + O(s-1), \qquad \frac1s = 1 - (s-1) + O\bigl((s-1)^2\bigr), \]
so the first term is $\frac{1}{(s-1)^2} - \frac{1+\gamma}{s-1} + O(1)$, which cancels the other two terms. In particular $s = 1$ is not a zero of $L(s,\chi)$ in either case.

\emph{The zeros.} Let $\rho$ be a zero of $L(s,\chi)$ with $\Re\rho > 0$, of multiplicity $m = m_\chi(\rho) \ge 1$. Then $\rho \ne 0, 1$, so $\frac{1}{s(s-1)}$ and $\frac{1}{s-1}$ are holomorphic at $\rho$, while $-\frac{L''}{L}(s,\chi)$ has a simple pole at $\rho$ with residue $-m$. Hence $H_\chi$ has a simple pole at $\rho$ with residue $-\frac{m}{\rho(\rho-1)} \ne 0$.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '106', 1, 'mellin-split-2026-11-24', '{"result_id":119,"body_tex":"\\emph{(i)} For $n \\ge 1$ and $\\Re s > 1$,\n\\[ \\int_1^\\infty \\Bigl(\\frac xn - 1\\Bigr)_+ x^{-s-1}\\,dx = \\int_n^\\infty \\Bigl(\\frac xn - 1\\Bigr) x^{-s-1}\\,dx = \\frac{n^{-s}}{s(s-1)}. \\]\nWith $\\sigma = \\Re s > 1$ and $\\Lambda \\ge 0$ this gives\n\\[ \\sum_{n \\ge 1} \\Lambda(n) \\int_1^\\infty \\Bigl(\\frac xn - 1\\Bigr)_+ x^{-\\sigma-1}\\,dx = \\frac{1}{\\sigma(\\sigma-1)} \\sum_{n \\ge 1} \\Lambda(n)\\, n^{-\\sigma} < \\infty, \\]\nso by Fubini the transform of $R_\\chi$ may be computed term by term:\n\\[ \\int_1^\\infty R_\\chi(x)\\, x^{-s-1}\\,dx = \\frac{1}{s(s-1)} \\sum_{n \\ge 1} \\Lambda(n)\\chi(n)\\, n^{-s} = -\\frac{L''}{L}(s,\\chi)\\,\\frac{1}{s(s-1)}. \\]\nTogether with\n\\[ \\int_1^\\infty x \\cdot x^{-s-1}\\,dx = \\frac1{s-1}, \\qquad \\int_1^\\infty x\\log x \\cdot x^{-s-1}\\,dx = \\frac1{(s-1)^2}, \\]\nthe definition of $G_\\chi$ and linearity give the formulas.\n\n\\emph{(ii)} The right-hand sides in (i) are meromorphic on $\\C$; they give the continuation. In $\\Re s > 0$ the rational factors are singular only at $s = 1$, and $-\\frac{L''}{L}(s,\\chi)$ is singular only at the zeros of $L(s,\\chi)$ and, for $\\chi = \\mathbf 1$, at the pole $s = 1$ of $\\zeta$.\n\n\\emph{No pole at $s = 1$.} For $\\chi \\ne \\mathbf 1$ we have $L(1,\\chi) \\ne 0$ \\cite{Davenport}, so $-\\frac{L''}{L}(s,\\chi)$ is holomorphic at $1$ with value $-b_\\chi$, and the first term is $-\\frac{b_\\chi}{s-1} + O(1)$, which cancels $\\frac{b_\\chi}{s-1}$. For $\\chi = \\mathbf 1$,\n\\[ -\\frac{\\zeta''}{\\zeta}(s) = \\frac{1}{s-1} - \\gamma + O(s-1), \\qquad \\frac1s = 1 - (s-1) + O\\bigl((s-1)^2\\bigr), \\]\nso the first term is $\\frac{1}{(s-1)^2} - \\frac{1+\\gamma}{s-1} + O(1)$, which cancels the other two terms. In particular $s = 1$ is not a zero of $L(s,\\chi)$ in either case.\n\n\\emph{The zeros.} Let $\\rho$ be a zero of $L(s,\\chi)$ with $\\Re\\rho > 0$, of multiplicity $m = m_\\chi(\\rho) \\ge 1$. Then $\\rho \\ne 0, 1$, so $\\frac{1}{s(s-1)}$ and $\\frac{1}{s-1}$ are holomorphic at $\\rho$, while $-\\frac{L''}{L}(s,\\chi)$ has a simple pole at $\\rho$ with residue $-m$. Hence $H_\\chi$ has a simple pole at $\\rho$ with residue $-\\frac{m}{\\rho(\\rho-1)} \\ne 0$.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');

-- corollary 8JS7 (id 120): Real poles have positive residues
INSERT INTO tags (tag, kind) VALUES ('8JS7', 'result');
INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (120, '8JS7', 'corollary', 'Real poles have positive residues', 'Let $\psi$ be a primitive character, and let $\Phi_\psi$ and $Z$ be as in \hyperref[8JS4]{the definition}. Every real $\rho \in Z$ satisfies $0 < \rho < 1$, and
\[ \operatorname{Res}_{s=\rho} \Phi_\psi > 0. \]', NULL, 104, 7, 'published', 1, 1, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '120', 1, 'mellin-split-2026-11-24', '{"tag":"8JS7","type":"corollary","title":"Real poles have positive residues","statement_tex":"Let $\\psi$ be a primitive character, and let $\\Phi_\\psi$ and $Z$ be as in \\hyperref[8JS4]{the definition}. Every real $\\rho \\in Z$ satisfies $0 < \\rho < 1$, and\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi > 0. \\]","section_id":104,"position":7,"listed":1,"aliases":["real-poles"]}', 'claude');
