INSERT INTO proofs (id, result_id, position, body_tex, body_html_cache, status, generated_by, generator_detail, reviewed_by, review_notes, created_at, updated_at, created_by, updated_by) VALUES (107, 120, 1, 'Every $L(s,\chi)$ is nonzero for $\Re s \ge 1$ \cite{Davenport}. A real $\rho \in Z$ is a zero of some $L(s,\chi)$ with $\rho > 0$, so $0 < \rho < 1$ and $\rho(\rho - 1) < 0$. By \ref{8JN4} and \ref{8JS5}(v),
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac{S_\rho}{\rho(1-\rho)} > 0. \]', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 10:45:00', '2026-11-24 10:45:00', 'claude', 'claude');
