-- 8JN4 (id 111): slimmed statement, new proof, position 6
UPDATE results SET title = 'Poles of $\Phi_\psi$', statement_tex = 'Let $\psi$ be a primitive character, and let $\Phi_\psi$, $Z$ and $S_\rho$ be as in \hyperref[8JS4]{the definition}. Then $\Phi_\psi$ extends meromorphically to $\Re s > 0$, and its poles there are exactly the points of $Z$. Each $\rho \in Z$ is a simple pole, with
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = -\frac{S_\rho}{\rho(\rho-1)}. \]', statement_html_cache = NULL, position = 6, revision = revision + 1, updated_at = '2026-11-24 10:45:00', updated_by = 'claude' WHERE id = 111;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '111', 3, 'mellin-split-2026-11-24', '{"tag":"8JN4","type":"lemma","title":"Poles of $\\Phi_\\psi$","statement_tex":"Let $\\psi$ be a primitive character, and let $\\Phi_\\psi$, $Z$ and $S_\\rho$ be as in \\hyperref[8JS4]{the definition}. Then $\\Phi_\\psi$ extends meromorphically to $\\Re s > 0$, and its poles there are exactly the points of $Z$. Each $\\rho \\in Z$ is a simple pole, with\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = -\\frac{S_\\rho}{\\rho(\\rho-1)}. \\]","section_id":104,"position":6,"listed":1,"aliases":["mellin-poles"]}', 'claude');
UPDATE proofs SET body_tex = 'For real $x$ we have $\overline{\chi(n)} = \bar\chi(n)$ and, for $\chi \ne \mathbf 1$, $\overline{L''(1,\chi)/L(1,\chi)} = L''(1,\bar\chi)/L(1,\bar\chi)$ by \ref{8JS5}(ii). Hence $\overline{G_\chi(x)} = G_{\bar\chi}(x)$ and $\Re G_\chi = \frac12(G_\chi + G_{\bar\chi})$. Since $\mathcal C_\psi$ is closed under $\chi \mapsto \bar\chi$ (\hyperref[8JG8]{definition}) and $\mathcal M$ is linear, for $\Re s > 1$
\[ \Phi_\psi(s) = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(H_\chi(s) + H_{\bar\chi}(s)\bigr). \]
By \ref{8JS6}(ii) the right-hand side is meromorphic on $\Re s > 0$; this is the continuation. Its only possible poles in $\Re s > 0$ are zeros of some $L(s,\chi)$ or $L(s,\bar\chi)$ with $\chi \in \mathcal C_\psi$, that is, points of $Z$, and each is at most simple. At $\rho \in Z$, adding the residues from \ref{8JS6}(ii) (a term with $m_\chi(\rho) = 0$ is holomorphic at $\rho$) gives
\[ \operatorname{Res}_{s=\rho} \Phi_\psi = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi\, \frac{-m_\chi(\rho) - m_{\bar\chi}(\rho)}{\rho(\rho-1)} = -\frac{S_\rho}{\rho(\rho-1)}. \]
This is nonzero because $S_\rho > 0$ by \ref{8JS5}(v), so every point of $Z$ is a pole.', body_html_cache = NULL, generator_detail = 'claude-opus-5-5', revision = revision + 1, updated_at = '2026-11-24 10:45:00', updated_by = 'claude' WHERE id = 101;
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '101', 2, 'mellin-split-2026-11-24', '{"result_id":111,"body_tex":"For real $x$ we have $\\overline{\\chi(n)} = \\bar\\chi(n)$ and, for $\\chi \\ne \\mathbf 1$, $\\overline{L''(1,\\chi)/L(1,\\chi)} = L''(1,\\bar\\chi)/L(1,\\bar\\chi)$ by \\ref{8JS5}(ii). Hence $\\overline{G_\\chi(x)} = G_{\\bar\\chi}(x)$ and $\\Re G_\\chi = \\frac12(G_\\chi + G_{\\bar\\chi})$. Since $\\mathcal C_\\psi$ is closed under $\\chi \\mapsto \\bar\\chi$ (\\hyperref[8JG8]{definition}) and $\\mathcal M$ is linear, for $\\Re s > 1$\n\\[ \\Phi_\\psi(s) = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(H_\\chi(s) + H_{\\bar\\chi}(s)\\bigr). \\]\nBy \\ref{8JS6}(ii) the right-hand side is meromorphic on $\\Re s > 0$; this is the continuation. Its only possible poles in $\\Re s > 0$ are zeros of some $L(s,\\chi)$ or $L(s,\\bar\\chi)$ with $\\chi \\in \\mathcal C_\\psi$, that is, points of $Z$, and each is at most simple. At $\\rho \\in Z$, adding the residues from \\ref{8JS6}(ii) (a term with $m_\\chi(\\rho) = 0$ is holomorphic at $\\rho$) gives\n\\[ \\operatorname{Res}_{s=\\rho} \\Phi_\\psi = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi\\, \\frac{-m_\\chi(\\rho) - m_{\\bar\\chi}(\\rho)}{\\rho(\\rho-1)} = -\\frac{S_\\rho}{\\rho(\\rho-1)}. \\]\nThis is nonzero because $S_\\rho > 0$ by \\ref{8JS5}(v), so every point of $Z$ is a pole.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
